import{_ as r}from"./chunks/2026-08-31-audit-failure-retry-p3-cutaway.BA-vmHzq.js";import{_ as i,C as o,o as n,c as s,a as t,E as d,a2 as c}from"./chunks/framework.Cm6XCzck.js";const v=JSON.parse('{"title":"The Action Succeeded. Why Did It Run Again?","description":"","frontmatter":{"title":"The Action Succeeded. Why Did It Run Again?","date":"2026-08-31","updated":"2026-08-31","column":"open-source-engineering","category":"daily","article_type":"engineering-case-study","edition":"research-center","research_question":"When an action has taken effect but a later audit write fails, why can an Agent Runtime not decide to retry from failed alone?","summary":"In an isolated fault experiment, the first local effect already existed when a completion-audit append reclassified the operation as failed. A later recovery in a new process created a second effect for a non-idempotent executor. Three executor controls show that execution state, effect fact, and retry eligibility are separate decisions.","sources":"/en/research/evidence/2026-08-31-runtime-continuity","project_relevance":"substantive-relationship","item_id":"RCR-20260831-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-31-audit-failure-retry-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/engineering/2026-08-31-audit-failure-retry.md","filePath":"en/engineering/2026-08-31-audit-failure-retry.md","lastUpdated":1788166937000}'),l={name:"en/engineering/2026-08-31-audit-failure-retry.md"};function h(u,e,p,f,y,m){const a=o("ArticleCover");return n(),s("div",null,[e[0]||(e[0]=t("p",null,[t("a",{href:"/joinwell52/zh/engineering/2026-08-31-audit-failure-retry"},"中文")],-1)),d(a,{image:"/assets/covers/daily-2026-08-31-audit-failure-retry-cover.png",kicker:"Runtime Continuity Research · 01",title:"The Action Succeeded. Why Did It Run Again?",summary:"A completion-audit failure cannot reauthorize an already-observed action for safe retry.",version:"RCR-20260831-01",status:"Engineering Case · 2026-08-31",languageHref:"/zh/engineering/2026-08-31-audit-failure-retry",languageLabel:"中文"}),e[1]||(e[1]=c('<h1 id="the-action-succeeded-why-did-it-run-again" tabindex="-1">The Action Succeeded. Why Did It Run Again? <a class="header-anchor" href="#the-action-succeeded-why-did-it-run-again" aria-label="Permalink to &quot;The Action Succeeded. Why Did It Run Again?&quot;">​</a></h1><p>After recovery completed, the operation had returned to <code>succeeded</code>, but the local effect record contained two entries.</p><p>This was neither concurrency nor a double click. The first action had completed and produced one effect record. Its completion-audit append then failed, and the Runtime reclassified the already-completed action as <code>failed</code>. After the audit destination was restored, the first process exited, and a new process resumed the approved operation. A second effect appeared.</p><p>The question is not whether retry is useful. It is narrower: <strong>when failure happens after the action, what evidence gives a Runtime permission to execute again?</strong> The central proposition is that execution state, effect fact, and retry eligibility are three different concepts. <code>failed</code> is not evidence that an action did not happen; it cannot by itself mean retry eligible.</p><p>CodeFlowMu is a local multi-Agent collaboration system that we develop and maintain. Multiple role-bearing Agents work on engineering tasks while the Runtime manages sessions, tool execution, human approval, and result records. We are both the system developers and the researchers for this experiment. The focus is what an operation actually did and how recovery should proceed, not whether a model answered well.</p><p>This distinction matters to the person operating recovery. Seeing <code>failed</code>, they must decide whether to run the action again, repair a record, or stop and verify the effect. Treating a record failure as an action failure can repeat an action already performed. Forbidding recovery in every case can block work that could safely continue.</p><p>V2.1.2 already strengthened <code>write_task</code> submission idempotency, ordinary event projection, and skill-session binding. Those are different paths. Response loss asks whether the caller received a successful result; this study asks what happens when the Runtime itself observed a successful action and a later recording step reclassified it. The former primarily tests idempotent replay. The latter first tests how retry eligibility is decided.</p><h2 id="_1-why-audit-failure-creates-a-retry-question" tabindex="-1">1. Why audit failure creates a retry question <a class="header-anchor" href="#_1-why-audit-failure-creates-a-retry-question" aria-label="Permalink to &quot;1. Why audit failure creates a retry question&quot;">​</a></h2><p>The external prompt came from <a href="https://github.com/zj-unicom-ai/UniEmployee" target="_blank" rel="noreferrer">UniEmployee</a>, an enterprise digital-employee platform that composes employee roles, workflows, skills, knowledge, connectors, tools, and approvals. Its administration audit work separates audit-write failure from the business response. That is not a universal policy: some operations must stop when audit is unavailable, while others may safely preserve their business result. The useful question is which layer an audit exception changes. <a href="https://github.com/zj-unicom-ai/UniEmployee/pull/17" target="_blank" rel="noreferrer">UniEmployee #17</a></p><p>We therefore inspected CodeFlowMu&#39;s <code>OperationApprovalService</code>, rather than proposing a generic transaction framework. The research is fixed at main commit <code>f0f42f01</code>; the V2.1.2 release worktree <code>919c3b48</code> has the same relevant source as tag <code>cb8869a3</code>. Source versions and hashes are in the <a href="/joinwell52/en/research/evidence/2026-08-31-runtime-continuity">evidence package</a>.</p><p>The service writes an operation record as JSON and then appends an audit event to JSONL. Atomic replacement of one JSON file does not make the record, audit file, and external action one transaction. The fault location determines what recovery may safely do.</p><h2 id="_2-four-fault-locations-are-not-one-execution-failure" tabindex="-1">2. Four fault locations are not one “execution failure” <a class="header-anchor" href="#_2-four-fault-locations-are-not-one-execution-failure" aria-label="Permalink to &quot;2. Four fault locations are not one “execution failure”&quot;">​</a></h2><p>The probe invokes the real product service. Its executor only appends a synthetic marker in an isolated directory; it does not push Git, create an issue, or call a remote system. The audit destination is turned into a directory at the original file path, so the actual append throws <code>EISDIR</code>.</p><table tabindex="0"><thead><tr><th>Probe</th><th>Fault location</th><th>What the caller sees</th><th>Persisted state</th><th style="text-align:right;">Effects already made</th></tr></thead><tbody><tr><td>P0</td><td>Execute again after normal completion</td><td><code>APPROVAL_ALREADY_CONSUMED</code></td><td>succeeded</td><td style="text-align:right;">1</td></tr><tr><td>P1</td><td>Approval record written; approval-audit append fails</td><td>error</td><td>approved</td><td style="text-align:right;">0</td></tr><tr><td>P2</td><td>executing written; start-audit append fails</td><td>error</td><td>executing</td><td style="text-align:right;">0</td></tr><tr><td>P3</td><td>effect complete; completion-audit append fails</td><td>error</td><td>failed</td><td style="text-align:right;">1</td></tr></tbody></table><p>The results agree on two fixed baselines. P0 is the necessary negative control: normal terminal success has a single-consumption guard. P3 does not imply that the approval service replays every action. <a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/fixtures/historical-probes.json">Captured probes</a></p><p>P1 shows that an error response does not mean approval was never persisted. P2 shows that <code>executing</code> does not mean the effect happened. P3 is the dangerous case: the effect happened, yet the record entered a state that recovery could treat as executable again.</p><p><img src="'+r+'" alt="One straight optical channel contains two cobalt effect markers separated by a narrow amber completion break."></p><p><em>Figure 1. The P3 relationship. The first effect evidence exists before the completion-record break; recovery can create a second effect. The image does not replace the P0–P3 data. Source: RCR-20260831 de-identified E-A0/E-A1 captures.</em></p><h2 id="_3-how-one-completion-failure-becomes-a-second-effect" tabindex="-1">3. How one completion failure becomes a second effect <a class="header-anchor" href="#_3-how-one-completion-failure-becomes-a-second-effect" aria-label="Permalink to &quot;3. How one completion failure becomes a second effect&quot;">​</a></h2><p>The source and captured state form one causal chain: an ADMIN approves the operation; the service persists <code>executing</code>; the executor creates a local effect and returns success evidence; the service persists <code>succeeded</code>; the completion-audit append fails in a <code>catch</code> shared with executor errors; the state becomes <code>failed</code>; recovery later accepts that still-approved failed operation and invokes the executor again without first treating the recorded first effect as a no-repeat condition.</p><p>The failed record still contains <code>kind=local-marker, observed_count=1</code>, and its independent effect snapshot contains <code>E1</code>. After recovery, the snapshot contains distinct <code>E1</code> and <code>E2</code> markers with the same synthetic <code>operation_key</code>. The state says failed while the first effect exists; recovery then makes another effect. <a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/fixtures/restart.json">Restart capture</a></p><p>To exclude an in-memory-only explanation, fault and recovery run in separate Node processes through the real <code>ControlledExecutorRegistry</code> request recalculation and dispatch path.</p><table tabindex="0"><thead><tr><th>Executor control</th><th style="text-align:right;">Effects after fault</th><th style="text-align:right;">Effects after new-process recovery</th><th style="text-align:right;">Calls</th><th>Recovery result</th></tr></thead><tbody><tr><td>No dedupe, same request digest</td><td style="text-align:right;">1</td><td style="text-align:right;">2</td><td style="text-align:right;">2</td><td>succeeded</td></tr><tr><td>Stable operation-key dedupe, same digest</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">2</td><td>succeeded</td></tr><tr><td>Recalculated request with changed digest</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td><code>APPROVAL_STALE</code></td></tr></tbody></table><p>The repeated run gives the same three relationships. This is not a production frequency estimate or a full executor survey. It does support the mechanism: a generic recovery layer may call again, but executor-side dedupe or a changed request digest can still prevent a second effect.</p><p>The more general result is:</p><blockquote><p><strong><code>failed ≠ effect_absent ≠ retry_allowed</code>.</strong></p></blockquote><p><code>failed</code> says a control path did not complete normally. It does not prove that an external action never happened. Retry eligibility must combine request identity, effect evidence, and executor dedupe capability; it cannot be inferred from one terminal field.</p><p>That gives three different recovery outcomes. Re-execute only when the request identity remains valid and evidence says the effect is absent. Reconcile records or audit when an effect exists or a stable operation key can identify it. Stop for verification when the effect cannot be confirmed and the executor cannot safely dedupe. This is an evidence-backed design direction, not an already-delivered automatic-recovery feature.</p><h2 id="_4-why-a-single-audit-failure-policy-cannot-be-copied" tabindex="-1">4. Why a single audit-failure policy cannot be copied <a class="header-anchor" href="#_4-why-a-single-audit-failure-policy-cannot-be-copied" aria-label="Permalink to &quot;4. Why a single audit-failure policy cannot be copied&quot;">​</a></h2><p><a href="https://github.com/paperclipai/paperclip" target="_blank" rel="noreferrer">Paperclip</a>, an open-source platform for managing multi-Agent work, provides a useful contrast. Its task-drain change makes durable audit writes transactional. If the audit write fails, in-process drain state is rolled back only where no later concurrent mutation occurred; a generation counter prevents stale restoration from overwriting newer state. Activity publication happens after commit, and publication failure is logged rather than re-presenting a committed drain as HTTP 500. <a href="https://github.com/paperclipai/paperclip/pull/12485" target="_blank" rel="noreferrer">Paperclip #12485</a></p><p>That code handles recoverable in-process drain state. It does not mean an already-sent issue, email, or payment can roll back with a local audit failure. External effects need their own evidence before retry.</p><h2 id="_5-recheck-and-boundary" tabindex="-1">5. Recheck and boundary <a class="header-anchor" href="#_5-recheck-and-boundary" aria-label="Permalink to &quot;5. Recheck and boundary&quot;">​</a></h2><p>The <a href="/joinwell52/en/research/evidence/2026-08-31-runtime-continuity">bilingual evidence guide</a> provides captured data, snapshots, checkers, and the product probe. Run <code>node check.mjs</code> in the downloaded evidence directory to verify public fixture consistency. Re-running the product service probe requires the fixed source and dependencies; the public package does not pretend that every reader can replay it.</p><p>The work includes 28 existing targeted tests as controls, not as a reliability score. It does not cover HTTP routes, real remote effects, power loss, or independent QA. To apply the method elsewhere, inject faults before action, after action, after result persistence, and during audit commit; then retry in a new process and count effects. The decisive question is not “was the last state failed?” but “did the prior call have an effect, and is calling again still safe?”</p><p><strong>The second run finally succeeded, but the first one had already succeeded too.</strong></p>',35))])}const w=i(l,[["render",h]]);export{v as __pageData,w as default};
